package org.circus.core;
import java.io.*;
import java.util.*;

/** Scalar lifetimes/word aliases. Providers here are explicit fixtures;
 * physical Win32 objects are checked separately, not inferred from numbers. */
public final class Pc1OsRegistryTests {
 private static int checks;private static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 private interface Work{void run()throws IOException;}
 private static void reject(Work work,String text)throws IOException{boolean failed=false;try{work.run();}catch(IOException expected){failed=expected.getMessage().contains(text);}check(failed,"precise "+text);}
 private static final class Provider implements Pc1OsRegistry.Binding {
  long physical;boolean alive=true;int publications,proofs,word;byte[] proof={17,31,47};Work publication;
  Provider(long physical){this.physical=physical;}
  public long physicalHandle()throws IOException{if(!alive)throw new IOException("actual owner closed");return physical;}
  public boolean live(){return alive;}
  public String contractId(){return "explicit fixture native owner V1";}
  public byte[] restorationProof(){proofs++;return proof.clone();}
  public void published(int raw)throws IOException{publications++;word=raw;if(publication!=null)publication.run();}
 }
 private static Pc1GuestAddressSpace space()throws IOException{return new Pc1GuestAddressSpace(Pc1GuestAddressSpace.Layout.imageHeapV1());}
 private static Pc1GuestAddressSpace.ExternalOwner key(String id)throws IOException{return new Pc1GuestAddressSpace.ExternalOwner("PC1_OS_FIXTURE_V1",id);}
 private static byte[] save(Pc1OsRegistry registry)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();registry.save(new DataOutputStream(bytes));return bytes.toByteArray();}
 private static Pc1OsRegistry.Image load(byte[] bytes)throws IOException{return Pc1OsRegistry.loadImage(new DataInputStream(new ByteArrayInputStream(bytes)));}
 private static Pc1GuestAddressSpace.Image layout(Pc1GuestAddressSpace space)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();space.saveLayout(new DataOutputStream(bytes),lease->-1);return Pc1GuestAddressSpace.loadLayout(new DataInputStream(new ByteArrayInputStream(bytes.toByteArray())));}
 private static void registerAndLookup()throws IOException{
  Pc1GuestAddressSpace space=space();Pc1OsRegistry registry=new Pc1OsRegistry(space);Provider small=new Provider(0x12345678);Pc1OsRegistry.Scalar a=registry.register(Pc1OsRegistry.Kind.FONT,key("font-1"),small);check(a.rawWord==0x12345678&&a.authority==Pc1OsRegistry.Authority.OBSERVED32_BIRTH&&space.mappingCount()==0,"true observed32 scalar is not fabricated readable memory");check(small.proofs==0&&small.publications==1,"registration does not read FILE header/hash or restoration proof");check(registry.register(Pc1OsRegistry.Kind.FONT,key("font-1"),small)==a&&small.publications==1,"same canonical binding registration idempotent");reject(()->registry.register(Pc1OsRegistry.Kind.FONT,key("other"),new Provider(small.physical)),"canonical registry binding");check(registry.lookup(a.rawWord,Pc1OsRegistry.Domain.GDI).physicalHandle()==small.physical,"known GDI object resolves its actual current provider");Provider bitmap=new Provider(0x22345678);Pc1OsRegistry.Scalar b=registry.register(Pc1OsRegistry.Kind.BITMAP,key("bitmap-1"),bitmap);check(registry.lookup(b.rawWord,Pc1OsRegistry.Domain.GDI).object.kind==Pc1OsRegistry.Kind.BITMAP,"GDI domain lookup does not pre-reject bitmap as a font-slot value");check(registry.lookup(b.rawWord,Pc1OsRegistry.Domain.USER).status==Pc1OsRegistry.Status.WRONG_DOMAIN,"known unrelated type namespace cannot become an arbitrary host HWND");check(registry.lookup(0,Pc1OsRegistry.Domain.GDI).status==Pc1OsRegistry.Status.NULL&&registry.lookup(-1,Pc1OsRegistry.Domain.USER).status==Pc1OsRegistry.Status.SENTINEL,"NULL/sentinel preserved for API-specific behavior");check(registry.lookup(0x76543210,Pc1OsRegistry.Domain.GDI).status==Pc1OsRegistry.Status.UNKNOWN,"unknown raw word never turns into a physical handle");reject(()->registry.lookup(0x76543210,Pc1OsRegistry.Domain.GDI).physicalHandle(),"not a known live");Pc1OsRegistry.Resolution captured=registry.lookup(a.rawWord,Pc1OsRegistry.Domain.GDI);small.alive=false;check(registry.lookup(a.rawWord,Pc1OsRegistry.Domain.GDI).status==Pc1OsRegistry.Status.CLOSED,"native owner closes without any Java alive mirror/callback");reject(captured::physicalHandle,"closed");
  Provider wide=new Provider(0x12345678000L);Pc1OsRegistry.Scalar token=registry.register(Pc1OsRegistry.Kind.WINDOW,key("wide-window"),wide);check(token.authority==Pc1OsRegistry.Authority.GUEST32_OPAQUE&&token.rawWord==0x20000000&&token.rawWord!=(int)wide.physical,"physical64 scalar uses common guest placement, not low32 truncation");reject(()->space.read(token.rawWord),"no readable ABI");reject(()->space.write(token.rawWord,0),"no writable ABI");wide.alive=false;check(registry.lookup(token.rawWord,Pc1OsRegistry.Domain.USER).status==Pc1OsRegistry.Status.CLOSED&&space.contains(token.rawWord),"closed status immediately borrows provider while view awaits owner-thread sync");registry.refreshClosed();check(!space.contains(token.rawWord)&&registry.lookup(token.rawWord,Pc1OsRegistry.Domain.USER).status==Pc1OsRegistry.Status.CLOSED,"refresh retires only opaque view, preserving stale word status");Provider newer=new Provider(0x98765432000L);Pc1OsRegistry.Scalar reused=registry.register(Pc1OsRegistry.Kind.WINDOW,key("new-window"),newer);check(reused.rawWord==token.rawWord&&registry.lookup(token.rawWord,Pc1OsRegistry.Domain.USER).object==reused,"reused scalar value naturally refers to newer lifetime");
 }
 private static void collisionsAndFile()throws IOException{
  Pc1GuestAddressSpace space=space();Pc1OsRegistry registry=new Pc1OsRegistry(space);Provider observed=new Provider(0x20000000);registry.register(Pc1OsRegistry.Kind.FONT,key("observed-handle"),observed);Pc1OsRegistry.Scalar wide=registry.register(Pc1OsRegistry.Kind.FONT,key("wide-handle"),new Provider(0x12300000000L));check(wide.rawWord==0x20000008&&!space.contains(0x20000000),"same-domain live observed handle vetoes opaque candidate without reserving numeric memory");Pc1HeapLease bytes=Pc1HeapLease.fixture32(0xe00000,new byte[]{1,2,3,4,5,6,7,8},"explicit memory-owner fixture");check(space.mapBorrowed(bytes)==0x20000000&&space.read(0x20000000)==1&&registry.lookup(0x20000000,Pc1OsRegistry.Domain.GDI).physicalHandle()==0x20000000L,"a real scalar handle value may equal an independent memory VA");
  Pc1GuestAddressSpace other=space();Pc1OsRegistry domains=new Pc1OsRegistry(other);domains.register(Pc1OsRegistry.Kind.WINDOW,key("observed-user"),new Provider(0x20000000));Pc1OsRegistry.Scalar gdi=domains.register(Pc1OsRegistry.Kind.FONT,key("wide-gdi"),new Provider(0x44440000000L));check(gdi.rawWord==0x20000000&&domains.lookup(gdi.rawWord,Pc1OsRegistry.Domain.USER).object.kind==Pc1OsRegistry.Kind.WINDOW&&domains.lookup(gdi.rawWord,Pc1OsRegistry.Domain.GDI).object==gdi,"opaque scalar domains stay separate while sharing one memory allocator");
  Provider file=new Provider(0x454);Pc1OsRegistry.Scalar f=registry.register(Pc1OsRegistry.Kind.FILE,key("source-1"),file);for(int tag=0;tag<4;tag++){Pc1OsRegistry.Resolution r=registry.lookupFile(f.rawWord|tag);check(r.status==Pc1OsRegistry.Status.LIVE&&r.object==f&&r.normalizedWord==0x454&&r.physicalHandle()==0x454,"independently verified FILE low2 tag "+tag);}check(registry.lookup(f.rawWord|1,Pc1OsRegistry.Domain.KERNEL).status==Pc1OsRegistry.Status.UNKNOWN,"generic kernel lookup does not silently inherit FILE tag semantics");Pc1OsRegistry.Scalar mutex=registry.register(Pc1OsRegistry.Kind.MUTEX,key("mutex"),new Provider(0x800));check(registry.lookupFile(mutex.rawWord|1).status==Pc1OsRegistry.Status.UNKNOWN,"FILE tag evidence does not normalize arbitrary mutex handle");file.alive=false;for(int tag=0;tag<4;tag++)check(registry.lookupFile(f.rawWord|tag).status==Pc1OsRegistry.Status.CLOSED,"closed FILE lowtag still queries same actual source owner");
 }
 private static void snapshots()throws IOException{
  Pc1GuestAddressSpace source=space();Pc1OsRegistry registry=new Pc1OsRegistry(source);Provider wide=new Provider(0x99900000000L),observed=new Provider(0x778899);Pc1OsRegistry.Scalar a=registry.register(Pc1OsRegistry.Kind.FILE,key("wide-file"),wide),b=registry.register(Pc1OsRegistry.Kind.FONT,key("observed-font"),observed);byte[] saved=save(registry);Pc1OsRegistry.Image image=load(saved);Pc1GuestAddressSpace.Image layout=layout(source);check(wide.proofs==1&&observed.proofs==1&&image.objects().get(0).owner.id.equals("wide-file"),"proof captured only at save and stable typed source identity exposed");Pc1GuestAddressSpace restored=Pc1GuestAddressSpace.emptyLike(layout);Provider newWide=new Provider(0xabc00000000L),newFont=new Provider(0xdef00000000L);Pc1OsRegistry copy=Pc1OsRegistry.restore(image,restored,layout,object->object.kind==Pc1OsRegistry.Kind.FILE?newWide:newFont);restored.restoreLayout(layout,Collections.emptyList());check(copy.lookupFile(a.rawWord|3).physicalHandle()==newWide.physical&&newWide.publications==1&&newWide.word==a.rawWord,"Guest scalar rebind/stage then publication once at saved VA");check(copy.lookup(b.rawWord,Pc1OsRegistry.Domain.GDI).physicalHandle()==newFont.physical&&newFont.word==b.rawWord,"observed-at-birth logical32 identity survives explicit physical64 rebind without truncation");check(restored.mappingCount()==1&&copy.findOwner(key("wide-file")).rawWord==a.rawWord,"sole layout carries opaque mapping exactly once");Provider bad=new Provider(0xabc00001000L);bad.proof=new byte[]{9};Pc1GuestAddressSpace rejected=Pc1GuestAddressSpace.emptyLike(layout);reject(()->Pc1OsRegistry.restore(image,rejected,layout,object->bad),"contract/lifetime/proof mismatch");check(rejected.mappingCount()==0&&bad.publications==0,"bad proof publishes no token/object association");
  wide.alive=false;byte[] closed=save(registry);Pc1GuestAddressSpace.Image closedLayout=layout(source);check(closedLayout.mappingCount()==0,"closed opaque view removed before sole layout capture");Pc1GuestAddressSpace closedSpace=Pc1GuestAddressSpace.emptyLike(closedLayout);Provider closedBinding=new Provider(-1);closedBinding.alive=false;Pc1OsRegistry closedCopy=Pc1OsRegistry.restore(load(closed),closedSpace,closedLayout,object->object.kind==Pc1OsRegistry.Kind.FILE?closedBinding:newFont);check(closedBinding.publications==1&&closedCopy.lookupFile(a.rawWord).status==Pc1OsRegistry.Status.CLOSED&&closedSpace.mappingCount()==0,"closed source association restored without reopening or faking physical memory");
 }
 private static void fences()throws IOException{
  Pc1GuestAddressSpace space=space();Pc1OsRegistry registry=new Pc1OsRegistry(space);Provider provider=new Provider(0x12300000000L);provider.publication=()->{reject(()->save(registry),"native publication");reject(()->layout(space),"active allocation/free");};registry.register(Pc1OsRegistry.Kind.FILE,key("published"),provider);check(provider.proofs==0,"publication fence does not eagerly demand restoration data");Provider failed=new Provider(0x12400000000L);failed.publication=()->{throw new IOException("required C association failed");};reject(()->registry.register(Pc1OsRegistry.Kind.FILE,key("failed"),failed),"C association failed");reject(()->save(registry),"incomplete native publication");
 }
 private static void distinctPhysicalRestore()throws IOException{
  Pc1GuestAddressSpace space=space();Pc1OsRegistry original=new Pc1OsRegistry(space);original.register(Pc1OsRegistry.Kind.FONT,key("first"),new Provider(0x1122));original.register(Pc1OsRegistry.Kind.FONT,key("second"),new Provider(0x3344));Pc1OsRegistry.Image image=load(save(original));Provider samePhysical=new Provider(0x5566);Pc1OsRegistry staged=new Pc1OsRegistry(space());reject(()->staged.restoreInto(image,null,object->samePhysical),"distinct saved lifetimes");check(samePhysical.publications==1,"second distinct native object cannot silently share first physical lifetime");reject(()->save(staged),"incomplete native publication");
 }
 public static int run()throws Exception{checks=0;registerAndLookup();collisionsAndFile();snapshots();fences();distinctPhysicalRestore();return checks;}
 public static void main(String[] args)throws Exception{System.out.println("PASS Pc1OsRegistryTests "+run());}
}
